#include <fstream>
#include <istream>
#include <ostream>
#include <string>

void formatEssay(std::istream& in, std::ostream& out, int n, int k) {
    int used = 0;
    for (int i = 0; i < n; ++i) {
        std::string word;
        in >> word;
        if (used + static_cast<int>(word.size()) > k) {
            out << '\n';
            used = 0;
        }
        if (used != 0) out << ' ';
        out << word;
        used += static_cast<int>(word.size());
    }
    out << '\n';
}

int main() {
    std::ifstream in("word.in");
    std::ofstream out("word.out");
    int n, k;
    in >> n >> k;
    formatEssay(in, out, n, k);
    return 0;
}
