#include <fstream>
#include <vector>

std::vector<int> restorePhoto(int n, const std::vector<int>& sums) {
    for (int first = 1; first <= n; ++first) {
        std::vector<int> a(n);
        std::vector<bool> seen(n + 1, false);
        a[0] = first;
        seen[first] = true;
        bool valid = true;
        for (int i = 1; i < n; ++i) {
            int next = sums[i - 1] - a[i - 1];
            if (next < 1 || next > n || seen[next]) {
                valid = false;
                break;
            }
            a[i] = next;
            seen[next] = true;
        }
        if (valid) return a;
    }
    return {}; // Unreachable on the original guaranteed-valid inputs.
}

int main() {
    std::ifstream in("photo.in");
    std::ofstream out("photo.out");
    int n;
    in >> n;
    std::vector<int> sums(n - 1);
    for (int& x : sums) in >> x;
    std::vector<int> answer = restorePhoto(n, sums);
    for (int i = 0; i < n; ++i) {
        if (i != 0) out << ' ';
        out << answer[i];
    }
    out << '\n';
    return 0;
}
