#include <fstream>

long long maxDistance(long long time, long long limit) {
    if (limit >= time) return time * (time + 1) / 2;
    long long rise = (time + limit) / 2;
    long long fall = time - rise;
    return rise * (rise + 1) / 2
         + fall * limit + fall * (fall - 1) / 2;
}

long long minimumTime(long long length, long long limit) {
    long long low = 0, high = length;
    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (maxDistance(mid, limit) >= length) high = mid;
        else low = mid + 1;
    }
    return low;
}

int main() {
    std::ifstream in("race.in");
    std::ofstream out("race.out");
    long long length;
    int n;
    in >> length >> n;
    while (n--) {
        long long limit;
        in >> limit;
        out << minimumTime(length, limit) << '\n';
    }
    return 0;
}
